const items = $input.all();

let totalMonto = 0;
let totalSolicitudes = 0;
let totalAprobadas = 0;
let detalle = [];

for (let i = 0; i < items.length; i++) {
  const reg = items[i].json;
  const cant = Number(reg.count_id_solicitud || reg.count || 0);
  const monto = Number(reg.sum_monto || reg.sum || 0);
  const ruta = reg.ruta || "SIN_RUTA";

  totalSolicitudes += cant;
  totalMonto += monto;

  if (ruta === "APROBACION") {
    totalAprobadas = cant;
  }

  detalle.push(ruta + ": " + cant + " solicitudes ($" + monto + ")");
}

let tasa = 0;
if (totalSolicitudes > 0) {
  tasa = Number(((totalAprobadas / totalSolicitudes) * 100).toFixed(1));
}

const mensaje = "Total de " + totalSolicitudes + " solicitudes procesadas por un monto de $" + totalMonto + " (Tasa aprobacion directa: " + tasa + "%). Detalle por ruta: " + detalle.join(" | ");

return [
  {
    json: {
      reporte: mensaje,
      total_solicitudes: totalSolicitudes,
      monto_acumulado: totalMonto,
      tasa_aprobacion: tasa
    }
  }
];
